/*!50003 CREATE*/ /*!50017 DEFINER=`sa`@`%`*/ /*!50003 TRIGGER utrigger_Rera_Agent_EventRecord_INSERT
AFTER INSERT
ON 
tbl_rera_authdesk_agent_eventaction
FOR EACH ROW
BEGIN  
    DECLARE v_AgentId BigInt; 
	Declare v_AgentDiaryNumber varchar(100);     
	Declare v_EventType int;    
    Declare v_RenewalAgentId BigInt;
    Declare v_RenewalAgentDiaryNumber varchar(100);
	Declare v_EventUserName varchar(200);
	Declare v_EventAction_Relationship varchar(150);

	DECLARE varchk_isdraft_membervalue int;
    
	Declare v_RCL_SeqCount int;
	Declare v_RCL_SeqCycleID int;
	Declare v_RCL_EventCycle_SequenceFlag varchar(100);
	Declare v_RCL_EventAction_BranchGroup varchar(50);
     
	Declare v_RCL_IsCP int; 
	Declare v_RCL_IsMO int; 
	Declare v_RCL_IsMT int; 
	Declare v_RCL_IsAL int; 
	Declare v_RCL_IsOR int;

	SET v_AgentId=NEW.Related_Agent_ID;         
	SET v_AgentDiaryNumber=NEW.Agent_DiaryNumber;           
	SET v_EventType=NEW.EventAction_Type;    
    SET v_RenewalAgentId=0;
    SET v_RenewalAgentDiaryNumber='NA';
    SET v_EventUserName=NEW.EventAction_IdentifiedBy;
	SET v_EventAction_Relationship=NEW.EventAction_Relationship;
    
   
 -- Activate ReApply Details
 If v_EventType = 220007      
 then      
   update tbl_RERA_Agent_RegDiaryNumber set IsDraft=0 where Agent_ID=v_AgentId and IsActive=1; 
   
   update tbl_rera_agent_profile set IsDraft=4 where Agent_ID=v_AgentId and IsActive=1 and IsDraft=5;
   update tbl_rera_agent_othermemberdetail set IsDraft=4 where Agent_ID=v_AgentId and IsActive=1 and IsDraft=5;
   update tbl_rera_agent_payment set IsDraft=4 where Agent_ID=v_AgentId and IsActive=1 and IsDraft=5;
   update tbl_rera_agent_documents set IsDraft=4 where Agent_ID=v_AgentId and IsActive=1 and IsDraft=5;
   update tbl_rera_agent_otherstateut_regreradetails set IsDraft=4 where Agent_ID=v_AgentId and IsActive=1 and IsDraft=5;
 
   -- -- Reminder Scheduler (Emails and SMS)
   call usp_insert_tbl_rera_agent_reminderscheduler_emails(v_AgentId, v_RenewalAgentId, v_AgentDiaryNumber, v_RenewalAgentDiaryNumber, v_EventType);
   call usp_insert_tbl_rera_agent_reminderscheduler_smsgateway(v_AgentId, v_RenewalAgentId, v_AgentDiaryNumber, v_RenewalAgentDiaryNumber, v_EventType);
 end if; 
 
 -- No Reply Found from Agent 
 If v_EventType = 220029      
 then
   select count(*) into varchk_isdraft_membervalue from tbl_RERA_Agent_RegDiaryNumber where Agent_ID=v_AgentId and IsActive=1 and IsDraftMember=0;
 
   if (varchk_isdraft_membervalue > 0)
   then
	   update tbl_RERA_Agent_RegDiaryNumber set IsDraft=1 where Agent_ID=v_AgentId and IsActive=1; 
   
	   update tbl_rera_agent_documents set IsDraft=1 where Agent_ID=v_AgentId and IsActive=1 and IsDraft in (0,4,5);
	   update tbl_rera_agent_othermemberdetail set IsDraft=1 where Agent_ID=v_AgentId and IsActive=1 and IsDraft in (0,4,5);
	   update tbl_rera_agent_payment set IsDraft=1 where Agent_ID=v_AgentId and IsActive=1 and IsDraft in (0,4,5);
	   update tbl_rera_agent_profile set IsDraft=1 where Agent_ID=v_AgentId and IsActive=1 and IsDraft in (0,4,5);
	   update tbl_rera_agent_otherstateut_regreradetails set IsDraft=1 where Agent_ID=v_AgentId and IsActive=1 and IsDraft in (0,4,5);
	   
	   -- -- Reminder Scheduler (Emails and SMS)
	   update tbl_rera_agent_reminderscheduler_emails set IsActive=2, D_Column=NOW() where Agent_ID=v_AgentId and IsActive=1 and AgentReminder_IndexID <> 0;
	   update tbl_rera_agent_reminderscheduler_smsgateway set IsActive=2, D_Column=NOW() where Agent_ID=v_AgentId and IsActive=1 and AgentReminderSMS_IndexID <> 0;
   end if;
 end if;
 
 
 -- Rejected or Withdrawn Application  
If ((v_EventType = 220005) or (v_EventType = 220099))
then
   select count(*) into varchk_isdraft_membervalue from tbl_RERA_Agent_RegDiaryNumber where Agent_ID=v_AgentId and IsActive=1 and IsDraftMember=0;

   if (varchk_isdraft_membervalue > 0)
   then
	   update tbl_RERA_Agent_RegDiaryNumber set IsDraft=1 where Agent_ID=v_AgentId and IsActive=1; 
   
	   update tbl_rera_agent_documents set IsDraft=1 where Agent_ID=v_AgentId and IsActive=1 and IsDraft in (0,4,5);
	   update tbl_rera_agent_othermemberdetail set IsDraft=1 where Agent_ID=v_AgentId and IsActive=1 and IsDraft in (0,4,5);
	   update tbl_rera_agent_payment set IsDraft=1 where Agent_ID=v_AgentId and IsActive=1 and IsDraft in (0,4,5);
	   update tbl_rera_agent_profile set IsDraft=1 where Agent_ID=v_AgentId and IsActive=1 and IsDraft in (0,4,5);
	   update tbl_rera_agent_otherstateut_regreradetails set IsDraft=1 where Agent_ID=v_AgentId and IsActive=1 and IsDraft in (0,4,5);
   end if;
end if;


-- Authority Desk CheckList - Approval and OpenFile
If ((v_EventType = 220011) or (v_EventType = 220051) or (v_EventType = 220052)) 
then
   SET v_RCL_IsCP=0; 
   SET v_RCL_IsMO=0; 
   SET v_RCL_IsMT=0; 
   SET v_RCL_IsAL=1; 
   SET v_RCL_IsOR=1;

   select count(*) into v_RCL_SeqCount from tbl_rera_authdesk_agent_eventaction_traybox_member where EventAction_Branch='ACLP' and Related_Agent_ID=v_AgentId and IsActive=1;
   IF (v_RCL_SeqCount<>0) THEN
   -- Already Exist Record
   
	   select EventCycle_SequenceID, EventCycle_SequenceFlag, IsCP, IsMO, IsMT, IsAL, IsOR 
       into v_RCL_SeqCycleID, v_RCL_EventCycle_SequenceFlag, v_RCL_IsCP, v_RCL_IsMO, v_RCL_IsMT, v_RCL_IsAL, v_RCL_IsOR
       from tbl_rera_authdesk_agent_eventaction_traybox_member 
       where EventAction_Branch='ACLP' and Related_Agent_ID=v_AgentId and IsActive=1;
       
       IF (v_RCL_EventCycle_SequenceFlag='Close') THEN
		   SET v_RCL_IsCP=0; 
		   SET v_RCL_IsMO=0; 
           SET v_RCL_IsMT=0; 
           SET v_RCL_IsAL=1; 
           SET v_RCL_IsOR=1;
       END IF;
       
       SET v_RCL_EventAction_BranchGroup='AL';
       select Occupation into v_RCL_EventAction_BranchGroup FROM userprofiledetails where UserName=v_EventUserName and IsActive=1 and IsDraft=1 and IsLock=1;
       If (v_EventType = 220051) Then
		   IF (v_RCL_EventAction_BranchGroup='CP') THEN
				SET v_RCL_IsCP=1; 
		   ELSE IF (v_RCL_EventAction_BranchGroup='MO') THEN
				SET v_RCL_IsMO=1;
		   ELSE IF (v_RCL_EventAction_BranchGroup='MT') THEN
				SET v_RCL_IsMT=1; 
		   END IF; 
		   END IF; 
		   END IF;       
       elseif (v_EventType = 220052) Then
		   IF (v_RCL_EventAction_BranchGroup='CP') THEN
				SET v_RCL_IsCP=3; 
		   ELSE IF (v_RCL_EventAction_BranchGroup='MO') THEN
				SET v_RCL_IsMO=3;
		   ELSE IF (v_RCL_EventAction_BranchGroup='MT') THEN
				SET v_RCL_IsMT=3;
		   END IF; 
		   END IF; 
		   END IF;
       end if;
       
       IF (v_RCL_EventCycle_SequenceFlag<>'Open') THEN
		   select max(EventCycle_SequenceID) into v_RCL_SeqCycleID from tbl_rera_authdesk_agent_eventaction_traybox_member where EventAction_Branch='ACLP' and Related_Agent_ID=v_AgentId;
		   IF (v_RCL_SeqCycleID IS NULL) THEN   
			  set v_RCL_SeqCycleID=1;
		   ELSE     
			  set v_RCL_SeqCycleID=v_RCL_SeqCycleID+1;
		   END IF;
       END IF;
       
       update tbl_rera_authdesk_agent_eventaction_traybox_member set IsActive=2 where EventAction_Branch='ACLP' and Related_Agent_ID=v_AgentId and IsActive=1;
       
	   INSERT INTO tbl_rera_authdesk_agent_eventaction_traybox_member 
	   (EventAction_Type, SubEventAction_Type, EventAction_Branch, EventAction_BranchGroup, EventCycle_SequenceID, EventCycle_SequenceFlag, SubEvent_IdentifiedBy, SubEvent_IdentifiedOn, Related_User_ID, Related_Agent_ID, Promoter_DiaryNumber, Agent_DiaryNumber, SubEvent_Summary, SubEvent_Description, SubEvent_Category, SubEvent_Aggregate, SubEvent_Relationship, IsCP, IsMO, IsMT, IsAL, IsOR, IsAcceptedStatus, AssignedTo, Target_ResolutionDate, Actual_ResolutionDate, IsBefore_TargetResolution, IsActive, IsDraft, CreatedBy, CreatedOn, ModifyBy, ModifyOn)
       VALUES (v_EventType, '0', 'ACLP', v_RCL_EventAction_BranchGroup, v_RCL_SeqCycleID, 'Open', v_EventUserName, NOW(), '0', v_AgentId, 'NA', v_AgentDiaryNumber, 'NA', 'NA', 'Authority Desk', 'ACLP', v_EventAction_Relationship, v_RCL_IsCP, v_RCL_IsMO, v_RCL_IsMT, v_RCL_IsAL, v_RCL_IsOR, 'NA', ' ', NOW(), NOW(), '0', '1', '0', v_EventUserName, NOW(), v_EventUserName, NOW());
   ELSE
	   -- NEW CYCLE
       SET v_RCL_EventAction_BranchGroup='AL';
       select Occupation into v_RCL_EventAction_BranchGroup FROM userprofiledetails where UserName=v_EventUserName and IsActive=1 and IsDraft=1 and IsLock=1;
       If (v_EventType = 220051) Then
		   IF (v_RCL_EventAction_BranchGroup='CP') THEN
				SET v_RCL_IsCP=1; 
		   ELSE IF (v_RCL_EventAction_BranchGroup='MO') THEN
				SET v_RCL_IsMO=1;
		   ELSE IF (v_RCL_EventAction_BranchGroup='MT') THEN
				SET v_RCL_IsMT=1; 
		   END IF; 
		   END IF; 
		   END IF;       
       elseif (v_EventType = 220052) Then
		   IF (v_RCL_EventAction_BranchGroup='CP') THEN
				SET v_RCL_IsCP=3; 
		   ELSE IF (v_RCL_EventAction_BranchGroup='MO') THEN
				SET v_RCL_IsMO=3;
		   ELSE IF (v_RCL_EventAction_BranchGroup='MT') THEN
				SET v_RCL_IsMT=3;
		   END IF; 
		   END IF; 
		   END IF;
       end if;
       
       INSERT INTO tbl_rera_authdesk_agent_eventaction_traybox_member 
       (EventAction_Type, SubEventAction_Type, EventAction_Branch, EventAction_BranchGroup, EventCycle_SequenceID, EventCycle_SequenceFlag, SubEvent_IdentifiedBy, SubEvent_IdentifiedOn, Related_User_ID, Related_Agent_ID, Promoter_DiaryNumber, Agent_DiaryNumber, SubEvent_Summary, SubEvent_Description, SubEvent_Category, SubEvent_Aggregate, SubEvent_Relationship, IsCP, IsMO, IsMT, IsAL, IsOR, IsAcceptedStatus, AssignedTo, Target_ResolutionDate, Actual_ResolutionDate, IsBefore_TargetResolution, IsActive, IsDraft, CreatedBy, CreatedOn, ModifyBy, ModifyOn)
	   VALUES (v_EventType, '0', 'ACLP', v_RCL_EventAction_BranchGroup, '1', 'Open', v_EventUserName, NOW(), '0', v_AgentId, 'NA', v_AgentDiaryNumber, 'NA', 'NA', 'Authority Desk', 'ACLP', v_EventAction_Relationship, v_RCL_IsCP, v_RCL_IsMO, v_RCL_IsMT, v_RCL_IsAL, v_RCL_IsOR, 'NA', ' ', NOW(), NOW(), '0', '1', '0', v_EventUserName, NOW(), v_EventUserName, NOW());
       
   END IF;
   
end if;

-- (I)  Authority Desk CheckList - Approval and CloseFile
-- (II) Agent Registration - LOCK (Approval or number allotted)
If ((v_EventType = 220008) or (v_EventType = 220012)) 
then
   -- Application Details
   update tbl_RERA_Agent_RegDiaryNumber set IsDraftMember=1 where Agent_ID=v_AgentId and IsActive=1 and IsDraft=1;

   select count(*) into v_RCL_SeqCount from tbl_rera_authdesk_agent_eventaction_traybox_member where Related_Agent_ID=v_AgentId and IsActive=1;
   IF (v_RCL_SeqCount<>0) THEN	
		update tbl_rera_authdesk_agent_eventaction_traybox_member set EventCycle_SequenceFlag='Close' where Related_Agent_ID=v_AgentId and IsActive=1;
   END IF;
   
end if;

-- No Reply Recieved within 15 days
If ((v_EventType = 220062)) 
then
   -- Agent Details  
   update tbl_RERA_Agent_RegDiaryNumber set IsDraftMember=1 where Agent_ID=v_AgentId and IsActive=1 and IsDraft=1;
   
end if;
 
       -- INSERT INTO CustomerLogs      
       -- VALUES(@CustomerId, ''''''''''''''''Inserted'''''''''''''''')      

END */;;
